def collatz_steps(n):
    """Count Collatz steps to reach 1."""
    def helper(x):
        if x == 1:
            return 0
        elif x % 2 == 0:
            return 1 + helper(x // 2)
        else:
            return 1 + helper(3 * x + 1)

    return helper(n)
```

