    """Spell out each digit of a number in English."""
    digit_map = {
        0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four',
        5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine',
        10: 'ten', 11: 'eleven', 12: 'twelve', 13: 'thirteen',
        14: 'fourteen', 15: 'fifteen', 16: 'sixteen', 17: 'seventeen',
        18: 'eighteen', 19: 'nineteen', 20: 'twenty',
        100: 'one hundred', 200: 'two hundred', 300: 'three hundred',
        400: 'four hundred', 500: 'five hundred',
        1000: 'one thousand'
    }
    words = []

    if n < 100:
        if n < 20:
            if n == 0:
                return "Zero"
            else:
                words.append(digit_map[n])
        else:
            words.append(digit_map[n % 20])
            return words + digit_map[20]
    else:
        if n < 1000:
            words.append(digit_map[n % 100])
        else:
            words.append(digit_map[100])

        if n % 10:
            return words + digit_map[10]
        else:
            return words

    return " ".join(words)

# test the function
print(digits_to_words(123))  # should print "one two three"
