import itertools
import math

class TreeNode:
    """Represents a node in a binary tree."""
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def all_trees(n):
    """
    Yields every structurally distinct binary tree with n nodes exactly once, 
    in a canonical order.
    """
    if n == 0:
        yield None
    else:
        for i, left in enumerate(all_trees(n - 1)):
            for right in all_trees(n - 1 - i):
                yield TreeNode(i + 1)  # Assign value to the root node
                yield from node_to_values(TreeNode(i + 1), left, right)

def node_to_values(node, left=None, right=None):
    """
    Yields a binary tree node as a tuple of values.
    """
    if node is None:
        yield ()
    else:
        yield from itertools.chain(
            node_to_values(node.left, left, right),
            node_to_values(node.right, right, left)
        )
        yield (node.val,) + node_to_values(None)

def count_trees(n):
    """
    Counts the number of structurally distinct binary trees with n nodes without 
    enumeration.
    """
    if n == 0:
        return 1
    else:
        return sum(count_trees(i) * count_trees(n - 1 - i) for i in range(n))

# Test cases
