```python
import math

def all_trees(n):
    """Generator function to yield every structurally distinct binary tree with n nodes exactly once, in a canonical order."""

    def generate_trees(left, right, path, n):
        if left > right:
            yield path
        else:
            for i in range(left, right + 1):
                yield from generate_trees(left, i - 1, path + [(left, i)], n)
                yield from generate_trees(i + 1, right, path + [(left, i)], n)

    for tree in generate_trees(1, n, [], n):
        yield Tree(tree)


class Tree:
    """Class to represent a binary tree."""

    def __init__(self, nodes):
        self.nodes = nodes

    def __eq__(self, other):
        if not isinstance(other, Tree):
            return False
        if len(self.nodes) != len(other.nodes):
            return False
        return self.nodes == other.nodes

    def __repr__(self):
        if not self.nodes:
            return 'Empty tree'
        result = ''
        for node in self.nodes:
            result += str(node) + ' '
        return '[' + result + ']'


def count_trees(n):
    """Function to count the number of structurally distinct binary trees with n nodes exactly once."""

    # Initialize a dictionary to store the count of trees of each size
    count = {0: 1}
    for i in range(1, n + 1):
        count[i] = 0
        for j in range(i):
            count[i] += count[j] * count[i - j - 1]
    return count[n]


