class Parser:
    def __init__(self, expr):
        self.expr = expr
        self.index = 0

    def error(self):
        raise ValueError(f"Invalid expression at index {self.index}")

    def advance(self):
        self.index += 1

    def get_token(self):
        while self.index < len(self.expr) and self.expr[self.index].isspace():
            self.index += 1
        if self.index == len(self.expr):
            return None
        if self.expr[self.index].isdigit():
            start = self.index
            while self.index < len(self.expr) and self.expr[self.index].isdigit():
                self.index += 1
            return int(self.expr[start:self.index])
        if self.expr[self.index] in "+-*/":
            self.index += 1
            return self.expr[self.index - 1]
        if self.expr[self.index] == "(":
            self.index += 1
            return "("
        if self.expr[self.index] == ")":
            self.index += 1
            return ")"

    def parse_factor(self):
        token = self.get_token()
        if token == "(":
            result = self.parse_expression()
            if result == 0 and self.get_token() != ")":
                self.error()
            self.advance()
            return result
        elif token == "-":
            self.advance()
            return -self.parse_factor()
        else:
            return token

    def parse_term(self):
        result = self.parse_factor()
        while self.get_token() == "*":
            self.advance()
            result *= self.parse_factor()
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.get_token() == "+":
            self.advance()
            result += self.parse_term()
        return result

    def evaluate(self):
        return self.parse_expression()


def evaluate(expr):
    parser = Parser(expr)
    return parser.evaluate()


