class Evaluator:
    def evaluate(self, expr):
        """
        Evaluates an arithmetic expression string containing integers, + - * /, parentheses, and unary minus.

        Args:
            expr (str): The arithmetic expression to evaluate.

        Returns:
            float: The result of the evaluated expression.

        Raises:
            ValueError: If the expression is invalid.
        """
        self.index = 0
        self.expr = expr
        self.num = ''

        def parse_expr():
            """Parses the expression and evaluates it."""
            return self.parse_term()

        def parse_term():
            """Parses a term and evaluates it."""
            result = self.parse_factor()
            while self.index < len(expr) and expr[self.index] in '+-':
                op = expr[self.index]
                self.index += 1
                factor = self.parse_factor()
                if op == '+':
                    result += factor
                elif op == '-':
                    result -= factor
            return result

        def parse_factor():
            """Parses a factor and evaluates it."""
            if expr[self.index] == '-':
                self.index += 1
                return -self.parse_floating_point()
            elif expr[self.index].isdigit() or expr[self.index] == '.':
                return self.parse_floating_point()
            elif expr[self.index] == '(':
                self.index += 1
                result = self.parse_expr()
                if expr[self.index] != ')':
                    raise ValueError("Invalid expression")
                self.index += 1
                return result
            elif expr[self.index] in '*/':
                op = expr[self.index]
                self.index += 1
                factor = self.parse_factor()
                if expr[self.index] != op:
                    raise ValueError("Invalid expression")
                self.index += 1
                result = factor
                while self.index < len(expr) and expr[self.index] in '*/':
                    op = expr[self.index]
                    self.index += 1
                    factor = self.parse_factor()
                    if op == '*':
                        result *= factor
                    elif op == '/':
                        result /= factor
                return result
            else:
                raise ValueError("Invalid expression")

        def parse_floating_point():
            """Parses a floating point number."""
            while self.index < len(expr) and (expr[self.index].isdigit() or expr[self.index] == '.'):
                self.num += expr[self.index]
                self.index += 1
            if self.num == '.':
                raise ValueError("Invalid expression")
            return float(self.num)

        try:
            return parse_expr()
        except IndexError:
            raise ValueError("Invalid expression")

    def __init__(self):
        pass


