class Evaluator:
    def __init__(self):
        self.operators = {
            '+': self.add,
            '-': self.sub,
            '*': self.mul,
            '/': self.div
        }

    def evaluate(self, expr):
        # Remove whitespace and split into tokens
        tokens = expr.replace(' ', '').split('(')
        tokens = [token.split(')')[0] for token in tokens]
        tokens = [token for token in tokens if token]

        # Recursive descent parser
        return self.parse(tokens)

    def parse(self, tokens):
        token = tokens.pop(0)
        if token.isdigit():
            return float(token)
        elif token[0] == '-':
            return -self.parse(tokens)
        elif token in self.operators:
            value1 = self.parse(tokens)
            if tokens and tokens[0] in self.operators:
                return self.operators[tokens.pop(0)](value1, self.parse(tokens))
            return self.operators[token](value1, self.parse(tokens))
        elif token == '(':
            value = self.parse(tokens)
            if tokens and tokens[0] == ')':
                tokens.pop(0)
                return value
            else:
                raise ValueError("Unbalanced parentheses")
        elif token == ')':
            return self.parse(tokens)
        else:
            raise ValueError("Invalid token")

    def add(self, value1, value2):
        return value1 + value2

    def sub(self, value1, value2):
        return value1 - value2

    def mul(self, value1, value2):
        return value1 * value2

    def div(self, value1, value2):
        if value2 == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        return value1 / value2

