    def longest_palindrome(self, s):
        def find_longest_palindrome(left, right):
            if s[left] == s[right]:
                return s[left:right+1]
            return None
        longest = None
        for i in range(len(s)):
            longest = max(longest, find_longest_palindrome(i, i + 1), find_longest_palindrome(i, i + 2), find_longest_palindrome(i, i + 3), find_longest_palindrome(i, i + 4))
        longest = max(longest, find_longest_palindrome(len(s) - 1, len(s) - 2), find_longest_palindrome(len(s) - 2, len(s) - 3), find_longest_palindrome(len(s) - 3, len(s) - 4), find_longest_palindrome(len(s) - 1, len(s) - 2))
        return longest

    def expandAroundCenter(self, s, left, right):
        while left > right:
            if s[left-1] == s[right]:
                return s[left-1:right+1]
            if s[left] == s[right]:
                return s[left:right+1]
            if s[left+1] == s[right]:
                return s[left+1:right+2]
            left -= 1
            right += 1
        return None

    def longest_palindrome(self, s):
        longest = None
        for i in range(len(s)):
            left = i
            right = i + 1
            while left <= right:
                longest = max(longest, self.expandAroundCenter(s, left, right))
                if left == right:
                    break
                left += 1
                right -= 1
        return longest


